package local.ondemand;
import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
/** Series shelf below episodes, with captured parent season and bounded metadata requests. */
final class SeriesRelated {
 final MainActivity a;final JSONObject original;final int season;final List<View> episodes,cards=new ArrayList<>();final LinearLayout section,row;final HorizontalScrollView scroll;final TextView note;int token;boolean loading,loaded;View lastEpisode,lastCard;
 SeriesRelated(MainActivity app,JSONObject full,int chosen,List<View> episodeCards){a=app;original=full;season=chosen;episodes=episodeCards;section=new LinearLayout(a);section.setTag("series-related:section");section.setOrientation(1);section.setPadding(0,a.dp(5),0,a.dp(5));TextView heading=a.text("More like this",16);section.addView(heading,new LinearLayout.LayoutParams(-1,a.dp(26)));note=a.text("Finding related series…",11);section.addView(note);scroll=new HorizontalScrollView(a);scroll.setTag("series-related:scroll");scroll.setFocusable(false);scroll.setHorizontalScrollBarEnabled(false);row=new LinearLayout(a);row.setPadding(a.dp(3),a.dp(3),a.dp(3),a.dp(3));scroll.addView(row);section.addView(scroll,new LinearLayout.LayoutParams(-1,a.dp(40)));a.rows.addView(section);resume();}
 boolean active(){return token==a.generation&&a.rows.findViewWithTag("series-related:section")==section&&!a.isDestroyed();}
 void resume(){if(loaded||loading&&token==a.generation)return;token=a.generation;loading=false;List<JSONObject> cached=a.similarCache.get("series:"+original.optString("id"));if(cached!=null){loaded=true;render(cached);}else load();}
 void load(){if(!active()||loading)return;loading=true;note.setVisibility(View.VISIBLE);note.setText("Finding related series…");final int requested=token;final Api api=a.api;a.relatedWorker.submit(()->{List<JSONObject> result=null;try{result=SimilarSeries.find(api,original,()->requested==a.generation&&!a.isDestroyed());}catch(Exception ignored){}final List<JSONObject> found=result;a.clock.post(()->{if(!active()||requested!=token)return;loading=false;if(found==null){note.setText("Related series unavailable");row.removeAllViews();Button retry=a.button("Retry related series",this::load);retry.setTag("series-related:retry");retry.setOnKeyListener((v,k,e)->{if(k!=19)return false;if(e.getAction()==0)up();return true;});row.addView(retry,new LinearLayout.LayoutParams(a.dp(190),a.dp(40)));scroll.getLayoutParams().height=a.dp(46);scroll.requestLayout();return;}loaded=true;a.similarCache.put("series:"+original.optString("id"),new ArrayList<>(found));render(found);});});}
 void render(List<JSONObject> found){row.removeAllViews();cards.clear();note.setText(found.isEmpty()?"No close series matches found":"");note.setVisibility(found.isEmpty()?View.VISIBLE:View.GONE);scroll.setVisibility(found.isEmpty()?View.GONE:View.VISIBLE);scroll.getLayoutParams().height=a.dp(142);scroll.requestLayout();for(JSONObject show:found){View card=PosterCard.create(a,show,"similar:series:"+show.optString("id"),()->open(show));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(a.dp(76),a.dp(134));p.rightMargin=a.dp(8);row.addView(card,p);cards.add(card);}for(int i=0;i<cards.size();i++){final int at=i;cards.get(i).setOnKeyListener((v,k,e)->{if(k!=19&&k!=20&&k!=21&&k!=22)return false;if(e.getAction()==0){lastCard=v;if(k==19)up();else if(k==21)cards.get(Math.max(0,at-1)).requestFocus();else if(k==22)cards.get(Math.min(cards.size()-1,at+1)).requestFocus();}return true;});}if(a.restoreFocus.startsWith("similar:series:")){final String tag=a.restoreFocus;View card=row.findViewWithTag(tag);if(card!=null)a.clock.post(()->{if(active()&&tag.equals(a.restoreFocus)){card.requestFocus();a.restoreFocus="";}});}}
 void enter(View episode){lastEpisode=episode;View target=lastCard!=null?lastCard:cards.isEmpty()?row.findViewWithTag("series-related:retry"):cards.get(0);if(target!=null)target.requestFocus();}
 void up(){View target=lastEpisode!=null?lastEpisode:episodes.isEmpty()?a.rows.findViewWithTag("season:"+season):episodes.get(0);if(target!=null)target.requestFocus();}
 void open(JSONObject show){View chosen=row.findViewWithTag("similar:series:"+show.optString("id"));if(chosen!=null)chosen.requestFocus();a.current=()->{a.screen(original.optString("name"),"");a.selected=original;a.type="series";TitlePages.series(a,original,season);};a.go(()->{a.selected=show;a.type="series";a.detail();});}
}
